screenPanels.initJs:
function(container, apiUrl, tables) {
  const resultTbody = container.querySelector("#result-tbody");
  const historyPanel = container.querySelector("#history-panel");
  let allRecords = [];
  let selectedRecordId = null;

  // ステータスバッジ色
  const statusColors = {
    draft: "#9fb0d1",
    pending: "#ffa500",
    active: "#4ade80",
    completed: "#60a5fa",
    cancelled: "#ef4444"
  };

  const statusLabels = {
    draft: "草案",
    pending: "承認待ち",
    active: "有効",
    completed: "完了",
    cancelled: "キャンセル"
  };

  // 1. 再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      resultTbody.innerHTML = `<tr style="background: rgba(0,0,0,0.2);"><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted);">該当する資料がありません</td></tr>`;
      return;
    }

    resultTbody.innerHTML = rows.map(r => {
      const type = r.contractType || r.type || "不明";
      const typeLabel = type === "contract" ? "契約書" : type === "proposal" ? "提案資料" : type;
      const status = r.status || "draft";
      const statusLabel = statusLabels[status] || status;
      const createdDate = r.createdAt ? new Date(r.createdAt).toLocaleDateString("ja-JP") : "—";
      const creatorName = r.creatorName || r.createdBy || "—";

      return `<tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer;" class="history-row">
        <td style="padding: 8px; color: var(--text);">${r.contractName || r.proposalName || r.name || "—"}</td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${typeLabel}</td>
        <td style="padding: 8px;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusColors[status] || "#666"}; color: #fff; font-size: 11px; font-weight: 500;">${statusLabel}</span>
        </td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${creatorName}</td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${createdDate}</td>
        <td style="padding: 8px; text-align: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.id}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データ描画
  if (tables[0] && tables[0].records) {
    allRecords = tables[0].records;
    renderRows([]);
  }

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-keyword").value.toLowerCase();
    const type = container.querySelector("#select-type").value;
    const status = container.querySelector("#select-status").value;
    const creator = container.querySelector("#input-creator").value.toLowerCase();
    const createdFrom = container.querySelector("#input-created-from").value;
    const createdTo = container.querySelector("#input-created-to").value;
    const updatedFrom = container.querySelector("#input-updated-from").value;
    const updatedTo = container.querySelector("#input-updated-to").value;

    // API から最新データ取得（複数テーブルを統合）
    let results = [];

    // 契約書テーブル（tableIndex 1 と仮定）
    if (tables[1]) {
      const contracts = await window.aivicApi.list(1) || tables[1].records || [];
      results = results.concat(contracts.map(c => ({
        ...c,
        type: "contract",
        contractName: c.contractName,
        contractType: c.contractType
      })));
    }

    // 提案資料テーブル（tableIndex 2 と仮定）
    if (tables[2]) {
      const proposals = await window.aivicApi.list(2) || tables[2].records || [];
      results = results.concat(proposals.map(p => ({
        ...p,
        type: "proposal",
        proposalName: p.proposalName || p.name
      })));
    }

    // フィルタリング
    const filtered = results.filter(r => {
      const name = (r.contractName || r.proposalName || r.name || "").toLowerCase();
      const desc = (r.description || r.explanation || "").toLowerCase();
      const rType = r.type || "";
      const rStatus = r.status || "";
      const rCreator = (r.creatorName || r.createdBy || "").toLowerCase();
      const rCreatedAt = r.createdAt ? new Date(r.createdAt) : null;
      const rUpdatedAt = r.updatedAt ? new Date(r.updatedAt) : null;

      const matchKeyword = !keyword || name.includes(keyword) || desc.includes(keyword);
      const matchType = !type || rType === type;
      const matchStatus = !status || rStatus === status;
      const matchCreator = !creator || rCreator.includes(creator);
      const matchCreatedFrom = !createdFrom || (rCreatedAt && rCreatedAt >= new Date(createdFrom));
      const matchCreatedTo = !createdTo || (rCreatedAt && rCreatedAt <= new Date(createdTo + "T23:59:59"));
      const matchUpdatedFrom = !updatedFrom || (rUpdatedAt && rUpdatedAt >= new Date(updatedFrom));
      const matchUpdatedTo = !updatedTo || (rUpdatedAt && rUpdatedAt <= new Date(updatedTo + "T23:59:59"));

      return matchKeyword && matchType && matchStatus && matchCreator && matchCreatedFrom && matchCreatedTo && matchUpdatedFrom && matchUpdatedTo;
    });

    allRecords = filtered;
    renderRows(filtered);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#input-keyword").value = "";
    container.querySelector("#select-type").value = "";
    container.querySelector("#select-status").value = "";
    container.querySelector("#input-creator").value = "";
    container.querySelector("#input-created-from").value = "";
    container.querySelector("#input-created-to").value = "";
    container.querySelector("#input-updated-from").value = "";
    container.querySelector("#input-updated-to").value = "";
    renderRows([]);
    historyPanel.innerHTML = `<div style="color: var(--text-muted); font-size: 12px; text-align: center; padding: 20px 0;">検索条件を入力して「検索」をクリックしてください</div>`;
    selectedRecordId = null;
  });

  // 5. 行クリック＆詳細ボタン：変更履歴を右パネルに表示
  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      selectedRecordId = recordId;
      const record = allRecords.find(r => r.id === recordId);

      if (!record) return;

      // 変更履歴を取得（契約変更履歴テーブル tableIndex 3 と仮定）
      let history = [];
      if (tables[3]) {
        const allHistory = await window.aivicApi.list(3) || tables[3].records || [];
        history = allHistory.filter(h => h.contractId === recordId || h.id === recordId);
      }

      // 右パネルに履歴を表示
      if (history.length === 0) {
        historyPanel.innerHTML = `
          <div style="color: var(--text-muted); font-size: 12px; padding: 12px; background: rgba(0,0,0,0.2); border-radius: 4px;">
            <strong>${record.contractName || record.proposalName || record.name}</strong><br/>
            <span style="font-size: 11px;">変更履歴なし</span>
          </div>
        `;
      } else {
        historyPanel.innerHTML = `
          <div style="color: var(--text-muted); font-size: 11px; padding: 8px; background: rgba(0,0,0,0.2); border-radius: 4px; margin-bottom: 8px;">
            <strong style="color: var(--text);">${record.contractName || record.proposalName || record.name}</strong><br/>
            ${history.length} 件の変更
          </div>
          ${history.map(h => {
            const changeDate = h.createdAt ? new Date(h.createdAt).toLocaleDateString("ja-JP") : "—";
            const changeType = h.changeType || h.type || "—";
            const status = h.changeStatus || h.status || "—";
            return `
              <div style="padding: 8px; background: rgba(0,0,0,0.2); border-left: 2px solid var(--primary); border-radius: 2px; font-size: 11px;">
                <div style="color: var(--text); font-weight: 500; margin-bottom: 2px;">${changeType}</div>
                <div style="color: var(--text-muted); margin-bottom: 2px;">日時: ${changeDate}</div>
                <div style="color: var(--text-muted); margin-bottom: 2px;">状態: <span style="color: var(--text);">${status}</span></div>
                ${h.changeReason ? `<div style="color: var(--text-muted); margin-top: 4px; padding-top: 4px; border-top: 1px solid rgba(255,255,255,0.1);">理由: ${h.changeReason}</div>` : ""}
              </div>
            `;
          }).join("")}
        `;
      }
    }
  });

  // 行クリックでも詳細表示
  container.addEventListener("click", async e => {
    const row = e.target.closest(".history-row");
    if (row && !e.target.closest(".detail-btn")) {
      const recordId = row.dataset.id;
      const detailBtn = row.querySelector(".detail-btn");
      if (detailBtn) detailBtn.click();
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 成果物納期 (0), 納期変更履歴 (1)
  const deliverableIndex = 0;
  const historyIndex = 1;

  // サンプルデータ（API未接続時の初期表示用）
  const sampleDeliverables = [
    { id: 'deliv-001', name: '営業レポート（月次）', currentDeadline: '2025-01-15', status: '完了', contractId: 'contract-001' },
    { id: 'deliv-002', name: 'ダッシュボード初版', currentDeadline: '2025-02-28', status: '進行中', contractId: 'contract-001' },
    { id: 'deliv-003', name: 'ユーザーマニュアル', currentDeadline: '2025-03-10', status: '計画中', contractId: 'contract-001' }
  ];

  const sampleHistory = [
    { id: 'hist-001', deliverableId: 'deliv-002', oldDeadline: '2025-01-15', newDeadline: '2025-02-20', reason: '要件追加により実装期間延長', status: '申請中', appliedDate: '2025-01-10', approver: null },
    { id: 'hist-002', deliverableId: 'deliv-002', oldDeadline: '2025-01-10', newDeadline: '2025-01-15', reason: '初期納期設定', status: '承認済', appliedDate: '2025-01-10', approver: '営業部長' }
  ];

  let selectedDeliverable = null;
  let currentHistory = [];

  // 1. 成果物一覧を描画
  function renderDeliverables(rows) {
    const tbody = container.querySelector('#deliverable-tbody');
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.status === '完了' ? '#90ee90' : r.status === '進行中' ? '#ffa500' : '#ff6b6b';
      return `<tr data-id="${r.id}" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px 8px; color: var(--text);">${r.name || ''}</td>
        <td style="padding: 6px 8px; text-align: center; color: ${statusColor}; font-size: 11px;">${r.status || ''}</td>
      </tr>`;
    }).join('');
  }

  // 2. 変更履歴タイムラインを描画
  function renderHistory(rows) {
    const timeline = container.querySelector('#history-timeline');
    if (!rows || rows.length === 0) {
      timeline.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">変更履歴はありません</div>';
      return;
    }
    timeline.innerHTML = rows.map(h => {
      const statusColor = h.status === '承認済' ? '#4caf50' : h.status === '申請中' ? '#ffa500' : '#ff6b6b';
      const statusLabel = h.status === '承認済' ? `承認済 (${h.appliedDate} by ${h.approver || '管理者'})` : h.status;
      return `<div style="padding: 8px; border-left: 2px solid ${statusColor}; background: rgba(${statusColor === '#4caf50' ? '76,175,80' : statusColor === '#ffa500' ? '255,165,0' : '255,107,107'},0.08); border-radius: 2px;">
        <div style="color: var(--text); font-weight: 600;">${h.oldDeadline} → ${h.newDeadline}</div>
        <div style="color: var(--text-muted); margin-top: 2px;">理由: ${h.reason || ''}</div>
        <div style="color: ${statusColor}; margin-top: 3px; font-weight: 600;">${statusLabel}</div>
      </div>`;
    }).join('');
  }

  // 3. 成果物選択時の詳細表示
  function selectDeliverable(id) {
    selectedDeliverable = sampleDeliverables.find(d => d.id === id);
    if (!selectedDeliverable) return;

    container.querySelector('[data-testid="deliverable-name-display"]').value = selectedDeliverable.name;
    container.querySelector('[data-testid="current-deadline"]').value = selectedDeliverable.currentDeadline;
    container.querySelector('[data-testid="change-status-display"]').textContent = '-';
    container.querySelector('[data-testid="apply-date-display"]').textContent = '-';
    container.querySelector('[data-testid="new-deadline"]').value = '';
    container.querySelector('[data-testid="change-reason"]').value = '';

    // 該当成果物の変更履歴を表示
    currentHistory = sampleHistory.filter(h => h.deliverableId === id);
    renderHistory(currentHistory);
  }

  // 4. 初期データ表示
  renderDeliverables(sampleDeliverables);
  renderHistory([]);

  // 5. 成果物行クリックで詳細表示
  container.addEventListener('click', e => {
    const row = e.target.closest('#deliverable-tbody tr');
    if (row) {
      const id = row.dataset.id;
      selectDeliverable(id);
      // 選択行をハイライト
      container.querySelectorAll('#deliverable-tbody tr').forEach(tr => tr.style.background = '');
      row.style.background = 'rgba(255,165,0,0.15)';
    }
  });

  // 6. 申請ボタン
  container.querySelector('[data-testid="apply-deadline-button"]').addEventListener('click', async () => {
    if (!selectedDeliverable) {
      alert('成果物を選択してください');
      return;
    }
    const newDeadline = container.querySelector('[data-testid="new-deadline"]').value;
    const reason = container.querySelector('[data-testid="change-reason"]').value;
    if (!newDeadline || !reason) {
      alert('変更後納期と変更理由を入力してください');
      return;
    }

    // API呼び出し（失敗時は自動通知）
    const result = await window.aivicApi.save(historyIndex, {
      deliverableId: selectedDeliverable.id,
      oldDeadline: selectedDeliverable.currentDeadline,
      newDeadline,
      reason,
      status: '申請中',
      appliedDate: new Date().toISOString().split('T')[0],
      approver: null
    });

    if (result) {
      alert('納期変更を申請しました');
      container.querySelector('[data-testid="change-status-display"]').textContent = '申請中';
      container.querySelector('[data-testid="apply-date-display"]').textContent = new Date().toISOString().split('T')[0];
      container.querySelector('[data-testid="new-deadline"]').value = '';
      container.querySelector('[data-testid="change-reason"]').value = '';
      // 履歴を再読み込み
      const updated = await window.aivicApi.list(historyIndex);
      if (updated) {
        currentHistory = updated.filter(h => h.deliverableId === selectedDeliverable.id);
        renderHistory(currentHistory);
      }
    }
  });

  // 7. クリアボタン
  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    container.querySelector('[data-testid="new-deadline"]').value = '';
    container.querySelector('[data-testid="change-reason"]').value = '';
  });

  // 8. 承認ボタン（管理者向け）
  container.querySelector('[data-testid="approve-button"]').addEventListener('click', async () => {
    if (currentHistory.length === 0) return;
    const latestHistory = currentHistory[0];
    const result = await window.aivicApi.update(historyIndex, latestHistory.id, {
      status: '承認済',
      approver: '管理者',
      appliedDate: new Date().toISOString().split('T')[0]
    });
    if (result) {
      alert('納期変更を承認しました');
      const updated = await window.aivicApi.list(historyIndex);
      if (updated) {
        currentHistory = updated.filter(h => h.deliverableId === selectedDeliverable.id);
        renderHistory(currentHistory);
      }
    }
  });

  // 9. 却下ボタン
  container.querySelector('[data-testid="reject-button"]').addEventListener('click', async () => {
    if (currentHistory.length === 0) return;
    const latestHistory = currentHistory[0];
    const result = await window.aivicApi.update(historyIndex, latestHistory.id, {
      status: '却下',
      approver: '管理者',
      appliedDate: new Date().toISOString().split('T')[0]
    });
    if (result) {
      alert('納期変更を却下しました');
      const updated = await window.aivicApi.list(historyIndex);
      if (updated) {
        currentHistory = updated.filter(h => h.deliverableId === selectedDeliverable.id);
        renderHistory(currentHistory);
      }
    }
  });

  // 10. 契約選択フィルタ
  container.querySelector('[data-testid="contract-select"]').addEventListener('change', e => {
    const contractId = e.target.value;
    if (!contractId) {
      renderDeliverables(sampleDeliverables);
    } else {
      const filtered = sampleDeliverables.filter(d => d.contractId === contractId);
      renderDeliverables(filtered);
    }
  });
}

function(container, apiUrl, tables) {
  // ===== 1. 要素取得 =====
  const contractSelect = container.querySelector("#contract-select");
  const invoiceCheckboxes = container.querySelectorAll(".invoice-checkbox");
  const deliverableCheckboxes = container.querySelectorAll(".deliverable-checkbox");
  const customerSelect = container.querySelector("#customer-select");
  const userCheckboxes = container.querySelectorAll(".user-checkbox");
  const deliveryDatetime = container.querySelector("#delivery-datetime");

  const previewInvoiceCount = container.querySelector("#preview-invoice-count");
  const previewDeliverableCount = container.querySelector("#preview-deliverable-count");
  const previewUserCount = container.querySelector("#preview-user-count");
  const previewDatetime = container.querySelector("#preview-datetime");
  const previewEmailInvoices = container.querySelector("#preview-email-invoices");
  const previewEmailDeliverables = container.querySelector("#preview-email-deliverables");
  const previewCustomer = container.querySelector("#preview-customer");
  const previewUsers = container.querySelector("#preview-users");
  const previewContract = container.querySelector("#preview-contract");

  const btnPreviewConfirm = container.querySelector("#btn-preview-confirm");
  const btnExecute = container.querySelector("#btn-execute");
  const btnCancel = container.querySelector("#btn-cancel");

  const confirmDialog = container.querySelector("#confirm-dialog");
  const dialogSummary = container.querySelector("#dialog-summary");
  const dialogConfirm = container.querySelector("#dialog-confirm");
  const dialogCancel = container.querySelector("#dialog-cancel");

  const successDialog = container.querySelector("#success-dialog");
  const successClose = container.querySelector("#success-close");

  // ===== 2. プレビュー更新関数 =====
  function updatePreview() {
    // 選択された請求書・成果物・ユーザーをカウント
    const selectedInvoices = Array.from(invoiceCheckboxes).filter(cb => cb.checked);
    const selectedDeliverables = Array.from(deliverableCheckboxes).filter(cb => cb.checked);
    const selectedUsers = Array.from(userCheckboxes).filter(cb => cb.checked);

    previewInvoiceCount.textContent = selectedInvoices.length + "件";
    previewDeliverableCount.textContent = selectedDeliverables.length + "件";
    previewUserCount.textContent = selectedUsers.length + "名";

    // 配信日時
    if (deliveryDatetime.value) {
      const dt = new Date(deliveryDatetime.value);
      previewDatetime.textContent = dt.toLocaleString('ja-JP');
    } else {
      previewDatetime.textContent = "未指定";
    }

    // メール本文プレビュー
    const invoiceLabels = selectedInvoices.map(cb => cb.parentElement.textContent.trim()).join("、");
    const deliverableLabels = selectedDeliverables.map(cb => cb.parentElement.textContent.trim()).join("、");
    previewEmailInvoices.textContent = invoiceLabels || "なし";
    previewEmailDeliverables.textContent = deliverableLabels || "なし";

    // 配信対象確認
    const customerLabel = customerSelect.options[customerSelect.selectedIndex]?.text || "未選択";
    previewCustomer.textContent = customerLabel;

    const userLabels = selectedUsers.map(cb => cb.parentElement.textContent.trim()).join("、");
    previewUsers.textContent = userLabels || "未選択";

    const contractLabel = contractSelect.options[contractSelect.selectedIndex]?.text || "未選択";
    previewContract.textContent = contractLabel;
  }

  // ===== 3. イベントリスナー登録 =====
  invoiceCheckboxes.forEach(cb => cb.addEventListener("change", updatePreview));
  deliverableCheckboxes.forEach(cb => cb.addEventListener("change", updatePreview));
  userCheckboxes.forEach(cb => cb.addEventListener("change", updatePreview));
  contractSelect.addEventListener("change", updatePreview);
  customerSelect.addEventListener("change", updatePreview);
  deliveryDatetime.addEventListener("change", updatePreview);

  // ===== 4. 配信内容確認ボタン =====
  btnPreviewConfirm.addEventListener("click", () => {
    const selectedInvoices = Array.from(invoiceCheckboxes).filter(cb => cb.checked);
    const selectedDeliverables = Array.from(deliverableCheckboxes).filter(cb => cb.checked);
    const selectedUsers = Array.from(userCheckboxes).filter(cb => cb.checked);

    if (!contractSelect.value) {
      alert("契約を選択してください");
      return;
    }
    if (selectedInvoices.length === 0 && selectedDeliverables.length === 0) {
      alert("請求書または成果物を選択してください");
      return;
    }
    if (!customerSelect.value) {
      alert("顧客企業を選択してください");
      return;
    }
    if (selectedUsers.length === 0) {
      alert("配信対象ユーザーを選択してください");
      return;
    }
    if (!deliveryDatetime.value) {
      alert("配信日時を指定してください");
      return;
    }

    // ダイアログに内容を表示
    const invoiceLabels = selectedInvoices.map(cb => cb.parentElement.textContent.trim()).join("<br>");
    const deliverableLabels = selectedDeliverables.map(cb => cb.parentElement.textContent.trim()).join("<br>");
    const userLabels = selectedUsers.map(cb => cb.parentElement.textContent.trim()).join("<br>");
    const contractLabel = contractSelect.options[contractSelect.selectedIndex].text;
    const customerLabel = customerSelect.options[customerSelect.selectedIndex].text;
    const dt = new Date(deliveryDatetime.value).toLocaleString('ja-JP');

    dialogSummary.innerHTML = `
      <div style="margin-bottom: 12px;">
        <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">契約</div>
        <div>${contractLabel}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">顧客企業</div>
        <div>${customerLabel}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">配信先ユーザー</div>
        <div>${userLabels}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">請求書</div>
        <div>${invoiceLabels || "なし"}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">成果物</div>
        <div>${deliverableLabels || "なし"}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">配信日時</div>
        <div>${dt}</div>
      </div>
    `;

    confirmDialog.removeAttribute("hidden");
  });

  // ===== 5. 配信実行ボタン（ダイアログ内） =====
  dialogConfirm.addEventListener("click", async () => {
    confirmDialog.setAttribute("hidden", "");

    // 配信データを構築
    const selectedInvoices = Array.from(invoiceCheckboxes).filter(cb => cb.checked).map(cb => cb.value);
