function(container, apiUrl, tables) {
  // ===== 1. データ構造の初期化 =====
  let selectedQuestionId = null;
  let questionsData = [];
  let evidenceData = [];

  // ===== 2. 質問一覧の再描画 =====
  function renderQuestionsList(questions) {
    const list = container.querySelector("#questions-list");
    list.innerHTML = questions.map(q => {
      const statusColor = q.status === 'answered' ? '#4ade80' : q.status === 'pending' ? '#fbbf24' : '#9ca3af';
      return `
        <div class="question-item" data-id="${q.id}" style="padding: 10px; border-radius: 3px; background: rgba(255,255,255,0.05); cursor: pointer; border-left: 3px solid ${statusColor}; transition: all 0.2s;" data-testid="question-item-${q.id}">
          <div style="font-size: 12px; color: var(--text); font-weight: 500; margin-bottom: 4px; line-height: 1.3;">${q.question_text || ''}</div>
          <div style="font-size: 11px; color: var(--text-muted);">${new Date(q.created_at).toLocaleDateString('ja-JP')}</div>
        </div>
      `;
    }).join("");
  }

  // ===== 3. 根拠資料一覧の再描画 =====
  function renderEvidenceList(evidence) {
    const list = container.querySelector("#evidence-list");
    if (!evidence || evidence.length === 0) {
      list.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px 0;">資料がアップロードされていません</div>';
      return;
    }
    list.innerHTML = evidence.map(e => `
      <div style="padding: 8px; background: rgba(0,0,0,0.2); border-radius: 3px; display: flex; align-items: center; justify-content: space-between; gap: 8px;">
        <div style="flex: 1; min-width: 0;">
          <div style="font-size: 12px; color: var(--text); font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${e.file_name || ''}</div>
          <div style="font-size: 11px; color: var(--text-muted);">${(e.file_size / 1024).toFixed(1)} KB</div>
        </div>
        <button class="evidence-download-btn" data-id="${e.id}" data-testid="evidence-download-${e.id}" style="background: transparent; border: none; color: var(--primary); cursor: pointer; font-size: 12px; padding: 4px 6px;">⬇️</button>
      </div>
    `).join("");
  }

  // ===== 4. 質問詳細の表示 =====
  function showQuestionDetail(questionId) {
    const q = questionsData.find(x => x.id === questionId);
    if (!q) return;

    selectedQuestionId = questionId;
    const detail = container.querySelector("#question-detail");
    detail.style.display = "block";
    container.querySelector("#detail-question-text").textContent = q.question_text || '';
    container.querySelector("#detail-question-date").textContent = new Date(q.created_at).toLocaleDateString('ja-JP');
    container.querySelector("#detail-question-status").textContent = 
      q.status === 'answered' ? '回答済' : q.status === 'pending' ? '未回答' : '確認中';

    // 既存回答があれば表示
    container.querySelector("#answer-text").value = q.answer_text || '';
    container.querySelector("#answer-status").value = q.answer_status || 'draft';
    container.querySelector("#publish-status").textContent = 
      q.answer_status === 'published' ? '公開済' : q.answer_status === 'ready' ? '公開準備中' : '下書き';
    container.querySelector("#publish-date").textContent = 
      q.answer_status === 'published' && q.published_at ? new Date(q.published_at).toLocaleString('ja-JP') : '-';

    // 質問アイテムのハイライト
    container.querySelectorAll(".question-item").forEach(el => {
      el.style.background = el.dataset.id === questionId ? 'rgba(255,255,255,0.1)' : 'rgba(255,255,255,0.05)';
    });
  }

  // ===== 5. 初期データ読み込み =====
  async function loadInitialData() {
    // 質問データ取得（テーブルインデックス 0 と仮定）
    const questions = await window.aivicApi.list(0);
    if (questions) {
      questionsData = questions;
      renderQuestionsList(questionsData);
      if (questionsData.length > 0) {
        showQuestionDetail(questionsData[0].id);
      }
    }

    // 根拠資料データ取得（テーブルインデックス 1 と仮定）
    const evidence = await window.aivicApi.list(1);
    if (evidence) {
      evidenceData = evidence;
      renderEvidenceList(evidenceData);
    }
  }

  loadInitialData();

  // ===== 6. 質問一覧のクリックイベント =====
  container.addEventListener("click", e => {
    const questionItem = e.target.closest(".question-item");
    if (questionItem) {
      showQuestionDetail(questionItem.dataset.id);
    }
  });

  // ===== 7. 回答保存ボタン =====
  container.querySelector("#btn-save-answer").addEventListener("click", async () => {
    if (!selectedQuestionId) {
      alert("質問を選択してください");
      return;
    }
    const answerText = container.querySelector("#answer-text").value.trim();
    const answerStatus = container.querySelector("#answer-status").value;
    if (!answerText) {
      alert("回答内容を入力してください");
      return;
    }
    const result = await window.aivicApi.update(0, selectedQuestionId, {
      answer_text: answerText,
      answer_status: answerStatus,
      status: 'answered'
    });
    if (result) {
      alert("回答を保存しました");
      loadInitialData();
    }
  });

  // ===== 8. 回答公開ボタン =====
  container.querySelector("#btn-publish-answer").addEventListener("click", async () => {
    if (!selectedQuestionId) {
      alert("質問を選択してください");
      return;
    }
    const answerText = container.querySelector("#answer-text").value.trim();
    if (!answerText) {
      alert("回答内容を入力してください");
      return;
    }
    const result = await window.aivicApi.update(0, selectedQuestionId, {
      answer_text: answerText,
      answer_status: 'published',
      published_at: new Date().toISOString(),
      status: 'answered'
    });
    if (result) {
      alert("回答を公開しました");
      loadInitialData();
    }
  });

  // ===== 9. ファイルアップロード =====
  const uploadZone = container.querySelector("#upload-zone");
  const fileInput = container.querySelector("#file-input");
  const uploadProgress = container.querySelector("#upload-progress");

  uploadZone.addEventListener("click", () => fileInput.click());
  uploadZone.addEventListener("dragover", e => {
    e.preventDefault();
    uploadZone.style.background = 'rgba(255,165,0,0.15)';
  });
  uploadZone.addEventListener("dragleave", () => {
    uploadZone.style.background = 'rgba(0,0,0,0.15)';
  });
  uploadZone.addEventListener("drop", e => {
    e.preventDefault();
    uploadZone.style.background = 'rgba(0,0,0,0.15)';
    handleFiles(e.dataTransfer.files);
  });

  container.querySelector("#btn-browse-file").addEventListener("click", () => fileInput.click());
  fileInput.addEventListener("change", e => handleFiles(e.target.files));

  async function handleFiles(files) {
    if (!selectedQuestionId) {
      alert("質問を選択してください");
      return;
    }
    uploadProgress.style.display = "block";
    for (const file of files) {
      const newEvidence = {
        question_id: selectedQuestionId,
        file_name: file.name,
        file_size: file.size,
        uploaded_at: new Date().toISOString()
      };
      const result = await window.aivicApi.save(1, newEvidence);
      if (!result) break;
    }
    uploadProgress.style.display = "none";
    loadInitialData();
  }

  // ===== 10. 参照ボタン =====
  container.querySelector("#btn-ref-contract").addEventListener("click", () => {
    alert("契約書参照機能は別画面で実装予定");
    window.showScreen("scr-1781957091729-pgcj");
  });
  container.querySelector("#btn-ref-proposal").addEventListener("click", () => {
    alert("提案資料参照機能は別画面で実装予定");
    window.showScreen("scr-1781957091729-pgcj");
  });
  container.querySelector("#btn-ref-deliverable").addEventListener("click", () => {
    alert("成果物参照機能は別画面で実装予定");
    window.showScreen("scr-1781957129236");
  });

  // ===== 11. 根拠資料ダウンロード =====
  container.addEventListener("click", e => {
    const downloadBtn = e.target.closest(".evidence-download-btn");
    if (downloadBtn) {
      const evidence = evidenceData.find(x => x.id === downloadBtn.dataset.id);
      if (evidence) {
        // 実装例：ファイルダウンロード処理
        alert(`${evidence.file_name} をダウンロードします`);
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const contractTableIdx = 0;      // 契約テーブル
  const changeHistoryTableIdx = 1; // 契約変更履歴テーブル
  const deliverableTableIdx = 2;   // 成果物テーブル
  const customerTableIdx = 3;      // 顧客企業テーブル

  // ===== 1. 初期データ取得と描画 =====
  async function initializeScreen() {
    // 顧客企業情報を表示（サンプル）
    const customers = tables[customerTableIdx]?.records || [];
    if (customers.length > 0) {
      const customer = customers[0];
      container.querySelector('[data-testid="customer-name"]').textContent = customer.企業名 || '顧客企業';
      container.querySelector('[data-testid="customer-industry"]').textContent = customer.業種 || '';
    }

    // 成果物納期を描画
    renderDeliverables();

    // 変更履歴を描画
    renderChangeHistory();
  }

  // ===== 2. 成果物納期テーブル描画 =====
  function renderDeliverables() {
    const deliverables = tables[deliverableTableIdx]?.records || [];
    const tbody = container.querySelector('#deliverables-tbody');

    if (deliverables.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="padding: 1rem; text-align: center; color: var(--text-muted);">成果物がありません</td></tr>';
      return;
    }

    tbody.innerHTML = deliverables.map(d => {
      const statusColor = d.ステータス === '完了' ? 'var(--primary)' : 
                          d.ステータス === '進行中' ? '#ffa500' : 'var(--text-muted)';
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 0.5rem; color: var(--text);">${d.成果物名 || '-'}</td>
          <td style="padding: 0.5rem; color: var(--text-muted); font-size: 0.75rem;">${d.納期 ? new Date(d.納期).toLocaleDateString('ja-JP') : '-'}</td>
          <td style="padding: 0.5rem; text-align: center;">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 3px; background: rgba(255,255,255,0.08); color: ${statusColor}; font-size: 0.75rem; font-weight: 500;">
              ${d.ステータス || '未定'}
            </span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ===== 3. 変更履歴タイムライン描画 =====
  function renderChangeHistory() {
    const history = tables[changeHistoryTableIdx]?.records || [];
    const timeline = container.querySelector('#change-history-timeline');

    if (history.length === 0) {
      timeline.innerHTML = '<div style="padding: 0.5rem; border-left: 2px solid rgba(255,255,255,0.1); color: var(--text-muted); font-size: 0.8rem;">変更履歴がありません</div>';
      return;
    }

    timeline.innerHTML = history.slice(0, 5).map(h => {
      const date = h.作成日時 ? new Date(h.作成日時).toLocaleDateString('ja-JP') : '-';
      const statusBg = h.変更ステータス === '承認済' ? 'rgba(76, 175, 80, 0.15)' : 'rgba(255,255,255,0.08)';
      const statusColor = h.変更ステータス === '承認済' ? '#4caf50' : 'var(--text-muted)';
      return `
        <div style="padding: 0.5rem; border-left: 2px solid ${statusColor}; background: ${statusBg}; border-radius: 2px;">
          <div style="font-size: 0.75rem; color: var(--text-muted);">${date}</div>
          <div style="font-size: 0.875rem; color: var(--text); font-weight: 500; margin: 0.25rem 0;">${h.変更種別 || '変更'}</div>
          <div style="font-size: 0.8rem; color: var(--text-muted);">${h.変更理由 || ''}</div>
          <div style="font-size: 0.75rem; color: ${statusColor}; margin-top: 0.25rem; font-weight: 500;">${h.変更ステータス || '-'}</div>
        </div>
      `;
    }).join('');
  }

  // ===== 4. ファイルアップロード処理 =====
  const fileDropZone = container.querySelector('#file-drop-zone');
  const fileInput = container.querySelector('#file-input');
  const fileList = container.querySelector('#file-list');
  let uploadedFiles = [];

  fileDropZone.addEventListener('click', () => fileInput.click());
  fileDropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    fileDropZone.style.background = 'rgba(255,165,0,0.15)';
  });
  fileDropZone.addEventListener('dragleave', () => {
    fileDropZone.style.background = 'rgba(0,0,0,0.15)';
  });
  fileDropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    fileDropZone.style.background = 'rgba(0,0,0,0.15)';
    handleFiles(e.dataTransfer.files);
  });
  fileInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
  });

  function handleFiles(files) {
    uploadedFiles = Array.from(files);
    fileList.innerHTML = uploadedFiles.map(f => `<div style="padding: 0.25rem 0; color: var(--text);">✓ ${f.name}</div>`).join('');
  }

  // ===== 5. 保存ボタン処理 =====
  const saveBtn = container.querySelector('[data-testid="save-button"]');
  saveBtn.addEventListener('click', async () => {
    // フォーム値を収集
    const contractId = container.querySelector('[data-testid="contract-select"]').value;
    const approverName = container.querySelector('[data-testid="approver-name"]').value;
    const agreementDate = container.querySelector('[data-testid="agreement-date"]').value;
    const changeContent = container.querySelector('[data-testid="change-content"]').value;
    const changeReason = document.querySelector('input[name="changeReason"]:checked')?.value || '';

    // 必須チェック
    if (!contractId || !approverName || !agreementDate) {
      alert('契約書、合意者名、合意日付は必須です');
      return;
    }

    // 合意項目チェック
    const agreeTerms = container.querySelector('[data-testid="agree-terms"]').checked;
    const agreePrice = container.querySelector('[data-testid="agree-price"]').checked;
    const agreeDeliverables = container.querySelector('[data-testid="agree-deliverables"]').checked;
    const agreeSchedule = container.querySelector('[data-testid="agree-schedule"]').checked;

    if (!agreeTerms || !agreePrice || !agreeDeliverables || !agreeSchedule) {
      alert('すべての合意項目にチェックしてください');
      return;
    }

    // 変更履歴を保存
    if (changeContent) {
      const changeHistoryData = {
        契約ID: contractId,
        変更種別: '合意確認',
        変更前値: '',
        変更後値: changeContent,
        変更理由: changeReason,
        変更ステータス: '承認済',
        申請者ID: 'current-user',
        承認者ID: 'current-user',
        承認日時: new Date().toISOString(),
        実行日時: new Date().toISOString(),
        備考: `合意者: ${approverName}, 合意日: ${agreementDate}`
      };

      const saved = await window.aivicApi.save(changeHistoryTableIdx, changeHistoryData);
      if (!saved) {
        alert('変更履歴の保存に失敗しました');
        return;
      }
    }

    alert('合意確認が保存されました');
    renderChangeHistory();

    // フォームをリセット
    container.querySelector('[data-testid="contract-select"]').value = '';
    container.querySelector('[data-testid="approver-name"]').value = '';
    container.querySelector('[data-testid="agreement-date"]').value = '';
    container.querySelector('[data-testid="change-content"]').value = '';
    document.querySelectorAll('input[name="changeReason"]').forEach(r => r.checked = false);
    uploadedFiles = [];
    fileList.innerHTML = '';
  });

  // ===== 6. キャンセルボタン処理 =====
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');
  cancelBtn.addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      container.querySelector('[data-testid="contract-select"]').value = '';
      container.querySelector('[data-testid="approver-name"]').value = '';
      container.querySelector('[data-testid="agreement-date"]').value = '';
      container.querySelector('[data-testid="change-content"]').value = '';
      document.querySelectorAll('input[type="checkbox"]').forEach(c => c.checked = false);
      document.querySelectorAll('input[name="changeReason"]').forEach(r => r.checked = false);
      uploadedFiles = [];
      fileList.innerHTML = '';
    }
  });

  // ===== 7. 契約選択時にサマリーを更新 =====
  const contractSelect = container.querySelector('[data-testid="contract-select"]');
  contractSelect.addEventListener('change', () => {
    const contracts = tables[contractTableIdx]?.records || [];
    const selected = contracts.find(c => c.契約ID === contractSelect.value);

    if (selected) {
      container.querySelector('[data-testid="contract-amount"]').textContent = 
        `¥${(selected.契約金額 || 0).toLocaleString('ja-JP')}`;

      const startDate = selected.契約開始日 ? new Date(selected.契約開始日).toLocaleDateString('ja-JP') : '-';
      const endDate = selected.契約終了日 ? new Date(selected.契約終了日).toLocaleDateString('ja-JP') : '-';
      container.querySelector('[data-testid="contract-period"]').textContent = `${startDate} ～ ${endDate}`;

      container.querySelector('[data-testid="contract-details"]').textContent = selected.契約内容 || '契約内容が表示されます';
    }
  });

  // ===== 初期化実行 =====
  initializeScreen();
}
